namespace ResearchAgent;

/// <summary>
/// Simple in-memory notepad for storing research findings.
/// </summary>
public sealed class Notepad
{
    private readonly List<NoteEntry> _notes = [];

    public IReadOnlyList<NoteEntry> Notes => _notes;

    public void Add(string content, string? source = null)
    {
        _notes.Add(new NoteEntry(content, source, DateTime.UtcNow));
    }

    public string GetAllNotes()
    {
        if (_notes.Count == 0)
            return "No notes taken yet.";

        return string.Join("\n\n", _notes.Select((n, i) =>
            $"[{i + 1}] {n.Content}{(n.Source is not null ? $" (Source: {n.Source})" : "")}"));
    }
}

public sealed record NoteEntry(string Content, string? Source, DateTime Timestamp);

using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json.Serialization;

namespace ResearchAgent;

/// <summary>
/// Tools available to the research agent for web search and note-taking.
/// </summary>
public sealed class ResearchTools(Notepad notepad)
{
    private static readonly HttpClient HttpClient = new()
    {
        Timeout = TimeSpan.FromSeconds(30),
    };

    [Description("Search the web for information on a given query. Returns a list of relevant results with titles, snippets, and URLs.")]
    public async Task<string> SearchWeb(
        [Description("The search query to look up")] string query)
    {
        try
        {
            // Use DuckDuckGo Instant Answer API (no key required)
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";

            var response = await HttpClient.GetFromJsonAsync<DdgResponse>(url);

            if (response is null)
                return "No results found.";

            var results = new List<string>();

            if (!string.IsNullOrEmpty(response.Abstract))
            {
                results.Add($"**Summary**: {response.Abstract}\nSource: {response.AbstractURL}");
            }

            foreach (var topic in response.RelatedTopics?.Take(5) ?? [])
            {
                if (!string.IsNullOrEmpty(topic.Text))
                {
                    results.Add($"- {topic.Text}\n  URL: {topic.FirstURL}");
                }
            }

            if (results.Count == 0)
                return $"No detailed results found for '{query}'. Try a different search query.";

            return $"Search results for '{query}':\n\n{string.Join("\n\n", results)}";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }

    [Description("Take a note to remember an important finding during research. Use this to record key facts, statistics, or insights.")]
    public string TakeNote(
        [Description("The content of the note to save")] string content,
        [Description("The source URL or reference for this information")] string? source = null)
    {
        notepad.Add(content, source);
        return $"Note saved. Total notes: {notepad.Notes.Count}";
    }

    [Description("Retrieve all notes taken so far during the research session.")]
    public string GetNotes()
    {
        return notepad.GetAllNotes();
    }
}

internal sealed class DdgResponse
{
    [JsonPropertyName("Abstract")]
    public string? Abstract { get; set; }

    [JsonPropertyName("AbstractURL")]
    public string? AbstractURL { get; set; }

    [JsonPropertyName("RelatedTopics")]
    public List<DdgTopic>? RelatedTopics { get; set; }
}

internal sealed class DdgTopic
{
    [JsonPropertyName("Text")]
    public string? Text { get; set; }

    [JsonPropertyName("FirstURL")]
    public string? FirstURL { get; set; }
}

