using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using Microsoft.Agents.AI;
using OpenAI;
using ResearchAgent;

var builder = Host.CreateApplicationBuilder(args);

var apiKey = builder.Configuration["AI:ApiKey"]
    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set AI:ApiKey in configuration or OPENAI_API_KEY environment variable.");

var modelId = builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18";

builder.Services.AddSingleton<Notepad>();
builder.Services.AddSingleton<ResearchTools>();

builder.Services.AddChatClient(services =>
    new ChatClientBuilder(
        new OpenAIClient(apiKey).GetChatClient(modelId).AsIChatClient())
    .UseFunctionInvocation(configure: opts => opts.MaximumIterationsPerRequest = 10)
    .Build(services));

var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var researchTools = host.Services.GetRequiredService<ResearchTools>();
var loggerFactory = host.Services.GetRequiredService<ILoggerFactory>();

var tools = new List<AITool>
{
    AIFunctionFactory.Create(researchTools.SearchWeb),
    AIFunctionFactory.Create(researchTools.TakeNote),
    AIFunctionFactory.Create(researchTools.GetNotes),
};

var agent = new ChatClientAgent(
    chatClient,
    name: "ResearchAgent",
    description: "An agent that researches topics by searching the web and taking notes.",
    instructions: """
        You are a research agent. When given a topic:
        1. Search the web for relevant information using multiple queries.
        2. Take notes on key findings as you discover them.
        3. After gathering sufficient information, review your notes and provide a
           comprehensive summary with key points and sources.
        Always cite your sources. Be thorough but concise.
        """,
    tools: tools,
    loggerFactory: loggerFactory,
    services: host.Services);

Console.WriteLine("=== Research Agent ===");
Console.Write("Enter a topic to research: ");
var topic = Console.ReadLine()?.Trim();

if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

var session = await agent.CreateSessionAsync(topic);

var response = await agent.RunAsync(
    $"Research the following topic and provide a comprehensive summary: {topic}",
    session);

Console.WriteLine(response.Text);

Console.WriteLine("\n=== Research Complete ===");

var notepad = host.Services.GetRequiredService<Notepad>();
if (notepad.Notes.Count > 0)
{
    Console.WriteLine($"\n[{notepad.Notes.Count} notes were taken during research]");
}

